import "./index.less";

// 弹窗按钮功能
class StoriesCollectionPopup {
    constructor() {
        this.popup = document.querySelector('.stories-banner-pop');
        this.closeIcon = document.querySelector('.pop-close-icon');
        this.popupButtons = document.querySelectorAll('[data-open-popup]');

        if (!this.popup) return;

        this.initEvents();
    }

    openPopup() {
        this.popup.style.display = 'block';
        document.body.style.overflow = 'hidden';
    }

    closePopup() {
        this.popup.style.display = 'none';
        document.body.style.overflow = '';
    }

    initEvents() {
        // 绑定所有弹窗按钮
        this.popupButtons.forEach(button => {
            button.addEventListener('click', (e) => {
                e.preventDefault();
                this.openPopup();
            });
        });

        // 点击右上角关闭图标
        if (this.closeIcon) {
            this.closeIcon.addEventListener('click', () => {
                this.closePopup();
            });
        }

        // 键盘 ESC 关闭弹窗
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                this.closePopup();
            }
        });
    }
}

// 活动 Banner
class LifeBanner {
    constructor({ DOM }) {
        this.DOM = DOM;

        const params = {
            injectStyles: [`
        .swiper-pagination-bullets.swiper-pagination-horizontal {
          display: flex;
          align-items: center;
          justify-content: center;
          bottom: 5.333333vw;
        }
        .swiper-pagination-bullet {
          width: 5.333333vw;
          height: 0.4vw;
          border-radius: 0;
          opacity: 1;
          background-color: rgba(255, 255, 255, 0.5);
          transition: all .3s ease-in-out;
        }
        .swiper-pagination-bullet-active {
          width: 13.333vw;
          background-color: #fff;
        }
        @media screen and (min-width: 1024px) {
          .swiper-pagination-bullets.swiper-pagination-horizontal {
            bottom: 2.222vw;
          }
          .swiper-pagination-bullet {
            width: 2.778vw;
            height: 0.139vw;
          }
          .swiper-pagination-bullet-active {
            width: 6.944vw;
          }
        }
        @media screen and (min-width: 1440px) {
          .swiper-pagination-bullets.swiper-pagination-horizontal {
            bottom: 32px;
          }
          .swiper-pagination-bullet {
            width: 40px;
            height: 2px;
          }
          .swiper-pagination-bullet-active {
            width: 100px;
          }
        }
      `],
            pagination: {
                clickable: true,
                renderBullet: function (index, className) {
                    return `<span class="${className}"></span>`;
                },
            },
        };

        Object.assign(this.DOM, params);
        this.DOM.initialize();
    }
}

class RenderViewMore {
    constructor() {
        this.main = document.querySelector('#MainContent');
        this.sections = document.querySelectorAll('.section-stories-collection');
        this.toggleViewMore = this.toggleViewMore.bind(this);
        this.resizeTimer = null;

        this.init();

        window.addEventListener('resize', () => {
            if (this.resizeTimer) clearTimeout(this.resizeTimer);
            this.resizeTimer = setTimeout(() => {
                if (this.isMobile()) {
                    this.sections.forEach(item => item.classList.remove('hidden'));
                    document.querySelector('.stories-view-more')?.classList?.add('hidden');
                } else {
                    document.querySelector('.stories-view-more')?.classList?.remove('hidden');
                }
            }, 500);
        });
    }

    isMobile() {
        return document.documentElement.clientWidth < 1024;
    }

    init() {
        if (this.sections.length > 4) {
            this.sections.forEach((item, index) => {
                item.classList.toggle('hidden', index > 3);
            });

            if (!document.querySelector('.stories-view-more')) {
                const viewMore = this.render();
                this.main.appendChild(viewMore);
                document.querySelector('.stories-view-more')
                  .addEventListener('click', this.toggleViewMore, false);
            }
        }
    }

    render() {
        const div = document.createElement('div');
        div.className = 'stories-view-more';
        div.innerHTML = `<span data-view-more="1">${window.page_productStrings.viewMore}</span>`;
        return div;
    }

    toggleViewMore(e) {
        const { viewMore } = e.target.dataset;
        if (viewMore === '1') {
            this.sections.forEach(item => item.classList.remove('hidden'));
            e.target.setAttribute('data-view-more', '0');
            e.target.innerHTML = window.pageInfo.cr === 'DE' ? 'WENIGER ANZEIGEN' : 'VIEW LESS';
        } else {
            this.sections.forEach((item, index) => {
                item.classList.toggle('hidden', index > 3);
            });
            e.target.setAttribute('data-view-more', '1');
            e.target.innerHTML = window.page_productStrings.viewMore;
        }
    }
}

function switchTab(type) {
    const $storyTab = $('.stories-item');
    const $filmsTab = $('.films-item');
    const $storyCards = $('.story-card-item--stories');
    const $filmCards = $('.story-card-item--films');
    const $storyNoCard = $('.no-card-container--stories');
    const $filmsNoCard = $('.no-card-container--films');

    if (type === 'stories') {
        $storyTab.addClass('active');
        $filmsTab.removeClass('active');
        $storyCards.show();
        $filmCards.hide();
        // 只有当Stories卡片数量为0时才显示Stories的缺失图
        if ($storyCards.length === 0) {
            $storyNoCard.show();
        } else {
            $storyNoCard.hide();
        }
        $filmsNoCard.hide();
    } else {
        $storyTab.removeClass('active');
        $filmsTab.addClass('active');
        $storyCards.hide();
        $filmCards.show();
        $storyNoCard.hide();
        // 只有当Films卡片数量为0时才显示Films的缺失图
        if ($filmCards.length === 0) {
            $filmsNoCard.show();
        } else {
            $filmsNoCard.hide();
        }
    }
}

function bindReadMoreBtn() {
    $('.read-more-btn').each(function () {
        $(this).off('click').on('click', function (e) {
            e.preventDefault();
            e.stopPropagation();

            const $btn = $(this);
            const $card = $btn.closest('.stories-item-card');
            const $overlay = $card.find('.hover-overlay');

            $btn.css('display', 'none');
            $overlay.css('opacity', 1);
        });
    });

    $('.hover-less-btn').each(function () {
        $(this).off('click').on('click', function (e) {
            e.preventDefault();
            e.stopPropagation();

            const $btn = $(this);
            const $card = $btn.closest('.stories-item-card');
            const $overlay = $card.find('.hover-overlay');
            const $readMoreBtn = $card.find('.read-more-btn');

            $overlay.css('opacity', 0);
            $readMoreBtn.css('display', 'block');
        });
    });
}

// 初始化排序功能
// sort 排序功能
function bindCustomSelect() {
    const select = document.getElementById('story-order-select');
    const trigger = select.querySelector('.select-trigger');
    const options = select.querySelector('.select-options');
    const items = select.querySelectorAll('.select-options li');
    const container = document.querySelector('.stories-gallery-items');


    if (!select || !container) {
        return;
    }

    // 缓存初始顺序
    const originalOrder = Array.from(container.children);

    // 展开/收起选项
    select.querySelector('.select-trigger-box').addEventListener('click', () => {
        // 使用getComputedStyle获取实际的display值，或者检查内联样式
        const computedStyle = window.getComputedStyle(options);
        const currentDisplay = options.style.display || computedStyle.display;
        const isOpen = currentDisplay === 'block';
        options.style.display = isOpen ? 'none' : 'block';
    });

    // 点击选项切换排序
    items.forEach(li => {
        li.addEventListener('click', () => {
            const value = li.dataset.value;
            trigger.textContent = li.textContent;

            // 切换 active 状态
            items.forEach(i => i.classList.remove('active'));
            li.classList.add('active');

            // 收起下拉
            options.style.display = 'none';

            // 排序逻辑
            if (value === 'desc') {
                const reversed = Array.from(container.children).reverse();
                container.innerHTML = '';
                reversed.forEach(node => container.appendChild(node));
            } else {
                container.innerHTML = '';
                originalOrder.forEach(node => container.appendChild(node));
            }
        });
    });

    // 点击外部关闭下拉
    document.addEventListener('click', (e) => {
        if (!select.contains(e.target)) {
            options.style.display = 'none';
        }
    });
}


// 初始化
document.addEventListener("DOMContentLoaded", () => {
    document.querySelectorAll('.life-story-kv').forEach(it => {
        new LifeBanner({ DOM: it });
    });

    new RenderViewMore();
    new StoriesCollectionPopup();

    $('.stories-item').on('click', () => switchTab('stories'));
    $('.films-item').on('click', () => switchTab('films'));

    bindReadMoreBtn();
    bindCustomSelect();
    
    // 设置初始状态，确保页面加载时显示正确的tab和缺失图
    switchTab('stories');
});
